import{_ as t,o as a,c as n,a3 as p}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"UPnPumpkin plugin API","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/upnpumpkin-api/docs/index.md"},"headers":[],"relativePath":"tools/upnpumpkin-api/docs/index.md","filePath":"tools/upnpumpkin-api/docs/index.md","lastUpdated":1791428389000}'),i={name:"tools/upnpumpkin-api/docs/index.md"};function o(s,e,r,l,d,u){return a(),n("div",null,[...e[0]||(e[0]=[p('<h1 id="upnpumpkin-plugin-api" tabindex="-1">UPnPumpkin plugin API <a class="header-anchor" href="#upnpumpkin-plugin-api" aria-label="Permalink to &quot;UPnPumpkin plugin API&quot;">​</a></h1><p><code>@pumpkin-plugins/upnpumpkin-api</code> lets one plugin request a leased port mapping from UPnPumpkin through Pumpkin plugin messages. It contains the message protocol, client, watcher, and helper for turning a successful mapping into a public URL.</p><h2 id="watch-a-mapping" tabindex="-1">Watch a mapping <a class="header-anchor" href="#watch-a-mapping" aria-label="Permalink to &quot;Watch a mapping&quot;">​</a></h2><p>Create a <code>PortMapClient</code> with the plugin message sender, then create a <code>MappingWatcher</code> with a stable key, protocol, internal port, and description. Start the watcher after the plugin loads, call <code>tick()</code> from the plugin&#39;s task handler, and call <code>stop()</code> when unloading or when the web service no longer needs the port.</p><p>The watcher requests a mapping immediately and refreshes it while running. <code>openUrl</code> returns a URL only when the reported state contains a usable public address. When UPnPumpkin is not installed or has not loaded yet, the watcher reports an unavailable state; callers should handle it without blocking their own service from starting.</p><p>Unused requests expire after five minutes. UPnPumpkin also applies a per-plugin mapping limit, so stop watchers promptly. The API package does not perform router discovery itself; the server-side plugin owns that network work.</p>',6)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
